// Returns the correct score for a dimension given the AI-inclusion toggle. Strategy
// and Customer have no AI-specific questions, so they're unaffected by the toggle.
function dimValue(d, dim, includeAI) {
  if (!d) return 0;
  if (includeAI || !dim.noAiKey) return d[dim.key];
  const v = d[dim.noAiKey];
  return v === null || v === undefined ? d[dim.key] : v;
}

